import React, { useEffect, useState } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { 
  ResponsiveContainer, LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend 
} from "recharts";
import { 
  Utensils, TrendingUp, Leaf, DollarSign, Users, Bell, LogOut, Settings, 
  PieChart, Truck, Calendar, PlusCircle, CheckCircle2, ShieldAlert, RefreshCw
} from "lucide-react";

function Dashboard() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("Overview");
  const [showModal, setShowModal] = useState(false);
  const [newDish, setNewDish] = useState("");
  const [newQuantity, setNewQuantity] = useState("");
  const [newRecipient, setNewRecipient] = useState("Feeding India NGO");
  const [toast, setToast] = useState(null);

  const fetchData = () => {
    setLoading(true);
    fetch("http://localhost:8000/api/forecast")
      .then((res) => res.json())
      .then((resData) => {
        setData(resData);
        setLoading(false);
      })
      .catch((err) => {
        console.error("API connection error:", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleLogSurplus = (e) => {
    e.preventDefault();
    if (!newDish || !newQuantity) return;

    fetch("http://localhost:8000/api/surplus/add", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ dish: newDish, quantity: newQuantity, recipient: newRecipient }),
    })
      .then((res) => res.json())
      .then(() => {
        setToast("Surplus logged & NGO notified!");
        setShowModal(false);
        setNewDish("");
        setNewQuantity("");
        fetchData();
        setTimeout(() => setToast(null), 3000);
      });
  };

  const navItems = [
    { label: "Overview", icon: PieChart },
    { label: "Demand Forecast", icon: TrendingUp },
    { label: "Meals & Attendance", icon: Utensils },
    { label: "Surplus Food", icon: ShieldAlert },
    { label: "Recipients", icon: Truck },
    { label: "Impact Analytics", icon: Leaf },
    { label: "Settings", icon: Settings },
  ];

  return (
    <div className="flex h-screen bg-slate-950 text-slate-100 overflow-hidden">
      {/* Toast Notification */}
      {toast && (
        <div className="fixed top-5 right-5 z-50 bg-emerald-600 text-white px-4 py-3 rounded-xl shadow-2xl flex items-center gap-2 border border-emerald-400 animate-bounce">
          <CheckCircle2 size={20} />
          <span className="font-medium text-sm">{toast}</span>
        </div>
      )}

      {/* Sidebar Navigation */}
      <aside className="w-64 bg-slate-900 border-r border-slate-800 flex flex-col justify-between">
        <div>
          {/* Logo Branding */}
          <div className="p-6 flex items-center gap-3 border-b border-slate-800">
            <div className="bg-emerald-500 p-2 rounded-xl text-slate-950 font-bold">
              <Utensils size={24} />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white">Plate<span className="text-emerald-400">AI</span></h1>
              <p className="text-xs text-slate-400">Canteen Control Room</p>
            </div>
          </div>

          {/* Navigation Links */}
          <nav className="p-4 space-y-1">
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.label;
              return (
                <button
                  key={item.label}
                  onClick={() => setActiveTab(item.label)}
                  className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                    isActive
                      ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 shadow-sm"
                      : "text-slate-400 hover:bg-slate-800/60 hover:text-slate-200"
                  }`}
                >
                  <Icon size={18} />
                  {item.label}
                </button>
              );
            })}
          </nav>
        </div>

        {/* User Profile Footer */}
        <div className="p-4 border-t border-slate-800">
          <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-xl border border-slate-800">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 rounded-full bg-emerald-500 text-slate-950 font-bold flex items-center justify-center text-sm">
                MS
              </div>
              <div className="overflow-hidden">
                <p className="text-xs font-semibold text-white truncate">Maya Sharma</p>
                <p className="text-[10px] text-slate-400 truncate">Canteen Manager</p>
              </div>
            </div>
            <button title="Sign Out" className="text-slate-400 hover:text-red-400 transition-colors p-1">
              <LogOut size={16} />
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col overflow-y-auto bg-slate-950">
        {/* Top App Bar */}
        <header className="px-8 py-5 bg-slate-900/50 border-b border-slate-800 flex items-center justify-between backdrop-blur-md sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
              {activeTab}
            </h2>
            <p className="text-xs text-slate-400">Real-time demand prediction & food loss mitigation</p>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={fetchData} 
              className="p-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl transition border border-slate-700"
              title="Refresh Data"
            >
              <RefreshCw size={18} className={loading ? "animate-spin text-emerald-400" : ""} />
            </button>

            <button 
              onClick={() => setShowModal(true)}
              className="flex items-center gap-2 bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-semibold px-4 py-2.5 rounded-xl text-sm transition shadow-lg shadow-emerald-500/20"
            >
              <PlusCircle size={18} />
              Log Surplus Food
            </button>
          </div>
        </header>

        {/* Dynamic Body Content */}
        <div className="p-8 space-y-8 max-w-7xl w-full mx-auto">
          {loading && !data ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400 gap-3">
              <RefreshCw size={32} className="animate-spin text-emerald-500" />
              <p className="text-sm">Fetching analytics from FastAPI backend...</p>
            </div>
          ) : data ? (
            <>
              {/* Dashboard Key Metrics Cards */}
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
                <MetricCard 
                  title="Today's Expected Demand" 
                  value={`${data.expected_demand} meals`} 
                  subtitle="Predicted via AI forecast"
                  icon={Users}
                  color="emerald"
                />
                <MetricCard 
                  title="Recommended Prep" 
                  value={`${data.recommended_prep} meals`} 
                  subtitle="+3.5% safety buffer"
                  icon={Utensils}
                  color="blue"
                />
                <MetricCard 
                  title="Actual Consumption" 
                  value={`${data.actual_consumption} meals`} 
                  subtitle="Live turnout feed"
                  icon={TrendingUp}
                  color="indigo"
                />
                <MetricCard 
                  title="Safe Surplus" 
                  value={`${data.safe_surplus} meals`} 
                  subtitle="Ready for NGO transfer"
                  icon={ShieldAlert}
                  color="amber"
                />
              </div>

              {/* Sustainability Impact Metrics */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
                <ImpactCard title="Food Saved" value={data.food_saved} icon={Utensils} badge="This Week" />
                <ImpactCard title="Cost Saved" value={data.cost_saved} icon={DollarSign} badge="Estimated" />
                <ImpactCard title="CO₂ Avoided" value={data.co2_avoided} icon={Leaf} badge="Green Metric" />
              </div>

              {/* Chart & Surplus Dispatch Table Grid */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Recharts Analytics Section */}
                <div className="lg:col-span-2 bg-slate-900 p-6 rounded-2xl border border-slate-800 shadow-xl">
                  <div className="flex items-center justify-between mb-6">
                    <div>
                      <h3 className="text-base font-semibold text-white">Predicted vs Actual Consumption</h3>
                      <p className="text-xs text-slate-400">Weekly comparison trends across all meal shifts</p>
                    </div>
                    <span className="text-xs bg-slate-800 text-slate-300 px-3 py-1.5 rounded-lg border border-slate-700">
                      7 Days View
                    </span>
                  </div>

                  <div className="h-72 w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <LineChart data={data.chart_data}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                        <XAxis dataKey="day" stroke="#94a3b8" />
                        <YAxis stroke="#94a3b8" />
                        <Tooltip 
                          contentStyle={{ backgroundColor: "#0f172a", borderColor: "#334155", borderRadius: "12px" }}
                          itemStyle={{ color: "#f8fafc" }}
                        />
                        <Legend />
                        <Line type="monotone" dataKey="predicted" name="Predicted Demand" stroke="#10b981" strokeWidth={3} dot={{ r: 4 }} />
                        <Line type="monotone" dataKey="actual" name="Actual Consumption" stroke="#6366f1" strokeWidth={3} dot={{ r: 4 }} />
                      </LineChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                {/* Active Surplus & Dispatch Feed */}
                <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 shadow-xl flex flex-col justify-between">
                  <div>
                    <div className="flex items-center justify-between mb-4">
                      <h3 className="text-base font-semibold text-white">Active Surplus Log</h3>
                      <span className="text-xs bg-emerald-500/10 text-emerald-400 px-2.5 py-1 rounded-md font-mono border border-emerald-500/20">
                        Live
                      </span>
                    </div>

                    <div className="space-y-3">
                      {data.surplus_items.map((item) => (
                        <div key={item.id} className="bg-slate-800/40 p-3.5 rounded-xl border border-slate-800 flex items-center justify-between">
                          <div>
                            <p className="text-sm font-semibold text-white">{item.dish}</p>
                            <p className="text-xs text-slate-400">{item.quantity} • {item.time_prepared}</p>
                            <p className="text-[11px] text-emerald-400 mt-1">Recipient: {item.recipient}</p>
                          </div>
                          <span className={`text-[10px] font-bold px-2.5 py-1 rounded-full uppercase tracking-wider ${
                            item.status === 'Claimed' 
                              ? 'bg-blue-500/10 text-blue-400 border border-blue-500/20' 
                              : 'bg-amber-500/10 text-amber-400 border border-amber-500/20'
                          }`}>
                            {item.status}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>

                  <button 
                    onClick={() => setShowModal(true)}
                    className="mt-6 w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-semibold rounded-xl border border-slate-700 transition"
                  >
                    + Add New Dispatch Batch
                  </button>
                </div>
              </div>
            </>
          ) : (
            <div className="p-12 text-center text-slate-500">
              <p>Failed to load data. Make sure the FastAPI backend is running on http://localhost:8000</p>
            </div>
          )}
        </div>
      </main>

      {/* Log Surplus Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 rounded-2xl max-w-md w-full p-6 shadow-2xl">
            <h3 className="text-lg font-bold text-white mb-1">Log Surplus Food</h3>
            <p className="text-xs text-slate-400 mb-6">Notify registered NGO partners for immediate food recovery dispatch.</p>

            <form onSubmit={handleLogSurplus} className="space-y-4">
              <div>
                <label className="text-xs text-slate-300 font-medium block mb-1">Dish Name</label>
                <input 
                  type="text" 
                  placeholder="e.g. Paneer Butter Masala" 
                  value={newDish} 
                  onChange={(e) => setNewDish(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3.5 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-emerald-500"
                  required
                />
              </div>

              <div>
                <label className="text-xs text-slate-300 font-medium block mb-1">Quantity</label>
                <input 
                  type="text" 
                  placeholder="e.g. 15 kg or 40 portions" 
                  value={newQuantity} 
                  onChange={(e) => setNewQuantity(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3.5 py-2.5 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-emerald-500"
                  required
                />
              </div>

              <div>
                <label className="text-xs text-slate-300 font-medium block mb-1">Assign NGO Recipient</label>
                <select 
                  value={newRecipient} 
                  onChange={(e) => setNewRecipient(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-xl px-3.5 py-2.5 text-sm text-white focus:outline-none focus:border-emerald-500"
                >
                  <option value="Feeding India NGO">Feeding India NGO</option>
                  <option value="Robin Hood Army">Robin Hood Army</option>
                  <option value="No Food Waste Trust">No Food Waste Trust</option>
                </select>
              </div>

              <div className="flex gap-3 pt-4">
                <button 
                  type="button" 
                  onClick={() => setShowModal(false)}
                  className="flex-1 py-2.5 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-sm font-semibold transition"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 py-2.5 bg-emerald-500 hover:bg-emerald-400 text-slate-950 rounded-xl text-sm font-semibold transition shadow-lg shadow-emerald-500/20"
                >
                  Log & Dispatch
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

